#!/usr/bin/env python3
"""
q0_verify.py — CONSOLIDATED EXECUTABLE VERIFICATION LAYER (C-CONS-2026-07-19)

Contains, byte-verbatim, all 48 Python instruments of the 488-file q0 archive,
plus the reconstructed q0_llm_verifier_v3.py shim (grade DERIVED; ledger
E-CONS-2; behaviorally certified by the v4 battery and the v5 22/22 battery
with zero case-level divergence from the archived validation record).

Companions: Q0_MASTER.md, Q0_LEDGER.md, q0_machine.json (registries,
contracts, data fixtures, and the full 488-file sha256 manifest).

USAGE
  python3 q0_verify.py list                      # every embedded script
  python3 q0_verify.py extract <name> [dir]      # write verbatim source(s)
  python3 q0_verify.py run <name> [-- args...]   # materialize deps + fixtures, run
  python3 q0_verify.py selftest                  # kernel-2.0 36-case battery
                                                 # + verifier v4 + v5 batteries
  python3 q0_verify.py hashes                    # embedded-source hash table

MATERIALIZATION RULES (ledger E-CONS-4/5)
  * Sources are embedded verbatim; run copies only receive a documented
    '/mnt/data' -> workdir rewrite so pre-C096 scripts execute (E-C096-20 class).
  * Any data file a script opens by name is auto-rehydrated from
    q0_machine.json (json_artifacts / csv_artifacts / fixtures), including the
    legacy space-named 'q0 registry.json' required by the kernel battery.
"""
import sys, os, json, subprocess, tempfile, hashlib, base64

VERIFIER_FAMILY = ["q0_llm_verifier_.py","q0_llm_verifier_v2.py",
  "q0_llm_verifier_v3.py","q0_llm_verifier_v4.py","q0_llm_verifier_v5.py"]
KERNEL_FAMILY = ["gate_kernel_v1_1.py","gate_kernel_v1_2.py","gate_kernel_v2_0.py"]

def _machine():
    here=os.path.dirname(os.path.abspath(__file__))
    p=os.path.join(here,"q0_machine.json")
    return json.load(open(p)) if os.path.exists(p) else None

def _materialize(work, names):
    for n in names:
        s=SOURCES[n].replace("/mnt/data", work)
        open(os.path.join(work,n),"w").write(s)

def _hydrate(work):
    m=_machine()
    if not m: return
    for k,v in m.get("json_artifacts",{}).items():
        if "_raw_text" in v and set(v)=={"_raw_text","_parse_error"}:
            open(os.path.join(work,k),"w").write(v["_raw_text"])
        else:
            json.dump(v, open(os.path.join(work,k),"w"), indent=1)
    for k,v in m.get("csv_artifacts",{}).items():
        open(os.path.join(work,k),"w").write(v)
    fx=m.get("fixtures",{}).get("q0 registry.json")
    if fx and fx["source"] in m.get("json_artifacts",{}):
        json.dump(m["json_artifacts"][fx["source"]],
                  open(os.path.join(work,"q0 registry.json"),"w"), indent=1)

def _run(name, args, keep=None):
    fam = set([name])
    if name in VERIFIER_FAMILY or name.startswith("validate_q0_llm"):
        fam |= set(VERIFIER_FAMILY)
    if "kernel" in name: fam |= set(KERNEL_FAMILY)
    fam |= {n for n in SOURCES if n != name and n[:-3] in SOURCES.get(name,"")}
    work = keep or tempfile.mkdtemp(prefix="q0v_")
    _materialize(work, fam & set(SOURCES)); _hydrate(work)
    r = subprocess.run([sys.executable, name]+list(args), cwd=work)
    print(f"[q0_verify] workdir: {work}")
    return r.returncode

def selftest():
    work = tempfile.mkdtemp(prefix="q0_selftest_")
    _materialize(work, set(SOURCES)); _hydrate(work)
    results={}
    for script, tag in [("validate_gate_kernel_v2_0.py","kernel_2_0_36case"),
                        ("validate_q0_llm_verifier_v4.py","verifier_v4"),
                        ("validate_q0_llm_verifier_v5.py","verifier_v5_22case")]:
        r=subprocess.run([sys.executable,script],cwd=work,
                         capture_output=True,text=True)
        ok = r.returncode==0
        out={}
        for cand in ["gate_kernel_v2_0_validation.json",
                     "q0_llm_verifier_v4_validation.json",
                     "q0_llm_verifier_v5_validation.json"]:
            p=os.path.join(work,cand)
            if os.path.exists(p):
                try: out[cand]=json.load(open(p))
                except Exception: pass
        summary=None
        if tag=="kernel_2_0_36case" and "gate_kernel_v2_0_validation.json" in out:
            d=out["gate_kernel_v2_0_validation.json"]
            summary=f'{d.get("passed_cases")}/{d.get("case_count")}'
            ok = ok and d.get("failed_cases")==0
        if tag=="verifier_v4" and "q0_llm_verifier_v4_validation.json" in out:
            ok = ok and out["q0_llm_verifier_v4_validation.json"].get("all_expected_checks_pass") is True
            summary="all_expected_checks_pass"
        if tag=="verifier_v5_22case" and "q0_llm_verifier_v5_validation.json" in out:
            d=out["q0_llm_verifier_v5_validation.json"]
            summary=f'{d.get("passed_cases")}/{d.get("case_count")}'
            ok = ok and d.get("failed_cases")==0
        results[tag]={"pass":ok,"summary":summary}
        print(f"  {tag:24} {'PASS' if ok else 'FAIL'}  {summary}")
    allok=all(v["pass"] for v in results.values())
    print(f"[q0_verify] SELFTEST {'PASS' if allok else 'FAIL'}  (workdir {work})")
    return 0 if allok else 1

def main():
    a=sys.argv[1:]
    if not a or a[0] in ("-h","--help"): print(__doc__); return 0
    cmd=a[0]
    if cmd=="list":
        for n in sorted(SOURCES): print(("  DERIVED " if n=="q0_llm_verifier_v3.py" else "  ")+n)
        return 0
    if cmd=="hashes":
        for n in sorted(HASHES): print(f"  {HASHES[n]:>16}  {n}")
        return 0
    if cmd=="extract":
        name=a[1]; d=a[2] if len(a)>2 else "."
        os.makedirs(d,exist_ok=True)
        open(os.path.join(d,name),"w").write(SOURCES[name])
        print(os.path.join(d,name)); return 0
    if cmd=="run":
        name=a[1]; args=a[3:] if len(a)>2 and a[2]=="--" else a[2:]
        return _run(name,args)
    if cmd=="selftest": return selftest()
    print("unknown command"); return 2

